const ov = await sdk.static.inspectWasm({view:"overview", startLine:1, lineCount:50});
const fns = await sdk.static.listFunctions({startIndex:0, limit:20});
const cp = await sdk.prepareCheckpoint({hypothesis:"reach gameplay then test right-hold motion", steps:[{buttons:1, frames:15, checkpoint:"title-exit"},{buttons:0, frames:15, checkpoint:"gameplay"}], watches:[]});
const tids = (cp.targets||[]).map(t=>t.id+":"+t.name+":"+t.type).join(",");
let exp=null;
if ((cp.targets||[]).length>0) {
  const t0 = cp.targets[0];
  let cur = 0;
  try { cur = t0.value ?? t0.currentValue ?? 0; } catch(e) {}
  const newVal = (typeof cur==="number") ? cur+20 : 20;
  exp = await sdk.runExperiment({hypothesis:"perturbing first checkpoint target changes motion/rendering vs control", checkpointId: cp.checkpointId, interventions:[{targetId:t0.id, value:newVal, hypothesis:"first target causal for motion"}], steps:[{buttons:32, frames:30, checkpoint:"hold-right"}], observations:{channels:["motion","rendering","events"], watches:[], captures:[]}});
} else {
  exp = await sdk.runExperiment({hypothesis:"right-hold motion baseline with no edit still yields paired control data", checkpointId: cp.checkpointId, interventions:[], steps:[{buttons:32, frames:30, checkpoint:"hold-right"}], observations:{channels:["motion","rendering","events"], watches:[], captures:[]}});
}
return JSON.stringify({overview:JSON.stringify(ov).slice(0,2000), fns:JSON.stringify(fns).slice(0,3000), cpId:cp.checkpointId, targets:tids, exp});

const fns = await sdk.static.listFunctions({startIndex:0, limit:15});
let finfo="nofns";
if (fns && fns.functions && fns.functions.length>0) { finfo = JSON.stringify(fns.functions.slice(0,3)).slice(0,600); }
const r = await sdk.readExperiment({artifactId:"337669261e9c548200065c25507c823c83e3bf8f4511da90ea9842b335f9932b", startFrame:1, frameCount:4});
return JSON.stringify({finfo, read:JSON.stringify(r).slice(0,1500)});

